from statistics import median


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}

    # Lattice rails recur at regular intervals in both dimensions. Prefer
    # sparse, regularly spaced line sets over a dominant checker/background.
    candidates = []
    for color in colors:
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.70 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.70 * h]
        if len(rows) < 2 or len(cols) < 2:
            continue

        def regularity(points):
            gaps = [b - a for a, b in zip(points, points[1:])]
            step = Counter(gaps).most_common(1)[0][0]
            regular = sum(g == step for g in gaps) / len(gaps)
            return step, regular

        rstep, rreg = regularity(rows)
        cstep, creg = regularity(cols)
        # A real rail has a consistent interval; background patterns usually
        # produce nearly every row/column and unit-sized gaps.
        score = rstep * cstep * rreg * creg
        if rstep > 1 and cstep > 1:
            candidates.append((score, color, rows, cols))
    if not candidates:
        raise ValueError('lattice rails not found')
    _, rail, row_lines, col_lines = max(candidates)

    # Most frequent non-rail color in the interiors is the empty tile value.
    interior = Counter(grid[r][c] for r in range(h) for c in range(w)
                       if r not in row_lines and c not in col_lines and grid[r][c] != rail)
    fill = interior.most_common(1)[0][0]

    # Decode a tile if at least three of its four rail intersections share a
    # non-rail, non-background marker color.
    out = []
    for r0, r1 in zip(row_lines, row_lines[1:]):
        row = []
        for c0, c1 in zip(col_lines, col_lines[1:]):
            corners = [grid[r][c] for r, c in ((r0, c0), (r0, c1), (r1, c0), (r1, c1))]
            counts = Counter(v for v in corners if v not in (rail, fill))
            marked = [color for color, n in counts.items() if n >= 3]
            row.append(marked[0] if marked else fill)
        out.append(row)

    # Crop unmarked outer margins, retaining any complete output pattern.
    while out and all(v == fill for v in out[0]):
        out.pop(0)
    while out and all(v == fill for v in out[-1]):
        out.pop()
    if not out:
        return [[fill]]
    while out[0] and all(row[0] == fill for row in out):
        for row in out:
            row.pop(0)
    while out[0] and all(row[-1] == fill for row in out):
        for row in out:
            row.pop()
    return out
